import (
	"bytes"
	"compress/zlib"
	"fmt"
	"io"
	"strings"
)

func compress(text string) []byte {
	var out bytes.Buffer
	w := zlib.NewWriter(&out)
	if _, err := io.WriteString(w, text); err != nil {
		panic(err)
	}
	if err := w.Close(); err != nil {
		panic(err)
	}
	return out.Bytes()
}
func decode(data []byte, budget int64) (string, error) {
	r, err := zlib.NewReader(bytes.NewReader(data))
	if err != nil {
		return "", err
	}
	defer r.Close()
	text, err := io.ReadAll(io.LimitReader(r, budget+1))
	if err != nil {
		return "", err
	}
	if int64(len(text)) > budget {
		return "", fmt.Errorf("expanded data over budget")
	}
	return string(text), nil
}
func main() {
	text, err := decode(compress("small"), 8)
	fmt.Printf("small=%s valid=%t\n", text, err == nil)
	_, err = decode(compress(strings.Repeat("a", 1000)), 8)
	fmt.Printf("expanded-rejected=%t\n", err != nil)
	text, err = decode(compress("12345678"), 8)
	fmt.Printf("exact-limit=%t\n", err == nil && len(text) == 8)
}

package main

import (
	"archive/tar"
	"bytes"
	"fmt"
	"io"
)

func main() {
	var archive bytes.Buffer
	w := tar.NewWriter(&archive)
	for _, item := range []struct{ name, text string }{{"notes.txt", "skip"}, {"docs/readme.txt", "offline guide"}} {
		if err := w.WriteHeader(&tar.Header{Name: item.name, Mode: 0600, Size: int64(len(item.text)), Typeflag: tar.TypeReg}); err != nil {
			panic(err)
		}
		if _, err := io.WriteString(w, item.text); err != nil {
			panic(err)
		}
	}
	if err := w.Close(); err != nil {
		panic(err)
	}
	r := tar.NewReader(bytes.NewReader(archive.Bytes()))
	found := ""
	for {
		h, err := r.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			panic(err)
		}
		if h.Name != "docs/readme.txt" {
			continue
		}
		if h.Typeflag != tar.TypeReg || h.Size > 64 {
			panic("invalid target")
		}
		data, err := io.ReadAll(r)
		if err != nil {
			panic(err)
		}
		found = string(data)
	}
	fmt.Printf("document=%s\nbytes=%d\n", found, len(found))
}

package main

import (
	"archive/zip"
	"bytes"
	"fmt"
	"io"
	"sort"
)

func main() {
	var data bytes.Buffer
	w := zip.NewWriter(&data)
	for _, item := range []struct{ name, text string }{{"sales.csv", "a,10\n"}, {"stock.csv", "a,3\n"}} {
		f, err := w.Create(item.name)
		if err != nil {
			panic(err)
		}
		if _, err = io.WriteString(f, item.text); err != nil {
			panic(err)
		}
	}
	if err := w.Close(); err != nil {
		panic(err)
	}
	r, err := zip.NewReader(bytes.NewReader(data.Bytes()), int64(data.Len()))
	if err != nil {
		panic(err)
	}
	rows := []string{}
	for _, file := range r.File {
		f, err := file.Open()
		if err != nil {
			panic(err)
		}
		body, err := io.ReadAll(f)
		f.Close()
		if err != nil {
			panic(err)
		}
		rows = append(rows, fmt.Sprintf("%s:%d", file.Name, len(body)))
	}
	sort.Strings(rows)
	for _, row := range rows {
		fmt.Println(row)
	}
	fmt.Printf("entries=%d\n", len(rows))
}

package main

import (
	"archive/zip"
	"fmt"
	"os"
	"path"
	"strings"
)

func safe(h *zip.FileHeader) bool {
	name := h.Name
	if name == "" || strings.Contains(name, "\\") || strings.Contains(name, ":") || path.IsAbs(name) || h.Mode()&os.ModeSymlink != 0 {
		return false
	}
	clean := path.Clean(name)
	return clean != "." && clean != ".." && !strings.HasPrefix(clean, "../")
}
func main() {
	for _, name := range []string{"docs/a.txt", "../escape", "/etc/file", "C:/file", "docs\\..\\escape"} {
		h := &zip.FileHeader{Name: name}
		fmt.Printf("%s=%t\n", name, safe(h))
	}
	link := &zip.FileHeader{Name: "docs/link"}
	link.SetMode(os.ModeSymlink | 0600)
	fmt.Printf("symlink=%t\n", safe(link))
}

package main

import (
	"archive/tar"
	"bytes"
	"fmt"
	"io"
	"sort"
)

func main() {
	var data bytes.Buffer
	w := tar.NewWriter(&data)
	for _, h := range []*tar.Header{{Name: "docs/", Mode: 0755, Typeflag: tar.TypeDir}, {Name: "docs/run.sh", Mode: 0750, Size: 3, Typeflag: tar.TypeReg}} {
		if err := w.WriteHeader(h); err != nil {
			panic(err)
		}
		if h.Size > 0 {
			if _, err := w.Write([]byte("go\n")); err != nil {
				panic(err)
			}
		}
	}
	if err := w.Close(); err != nil {
		panic(err)
	}
	r := tar.NewReader(bytes.NewReader(data.Bytes()))
	rows := []string{}
	for {
		h, err := r.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			panic(err)
		}
		kind := "file"
		if h.Typeflag == tar.TypeDir {
			kind = "dir"
		}
		rows = append(rows, fmt.Sprintf("%s %s %04o %d", h.Name, kind, h.Mode, h.Size))
	}
	sort.Strings(rows)
	for _, row := range rows {
		fmt.Println(row)
	}
}

package main

import (
	"bytes"
	"fmt"
	"io"
	"mime/multipart"
)

func main() {
	var wire bytes.Buffer
	w := multipart.NewWriter(&wire)
	if err := w.SetBoundary("qfli-boundary"); err != nil {
		panic(err)
	}
	if err := w.WriteField("owner", "Li"); err != nil {
		panic(err)
	}
	file, err := w.CreateFormFile("upload", "notes.txt")
	if err != nil {
		panic(err)
	}
	if _, err = io.WriteString(file, "line1\n"); err != nil {
		panic(err)
	}
	if err = w.Close(); err != nil {
		panic(err)
	}
	r := multipart.NewReader(&wire, w.Boundary())
	for {
		part, err := r.NextPart()
		if err == io.EOF {
			break
		}
		if err != nil {
			panic(err)
		}
		body, err := io.ReadAll(part)
		if err != nil {
			panic(err)
		}
		part.Close()
		fmt.Printf("field=%s file=%q body=%q\n", part.FormName(), part.FileName(), string(body))
	}
}

